// Paginate every job for the input domain via /api/v1/enrich.
//
// Why a Code node? n8n's HTTP Request + IF native loop is fragile when
// branches share item context. Doing the loop inside JS keeps the
// template readable and reliable. The pattern below is exactly what a
// downstream worker would do — copy-paste-friendly.
//
// Auth: reads `SUBSPACE_API_KEY` from your n8n instance environment.
// Set it on n8n via env var, or replace the line below with your
// literal key (`const apiKey = 'sk_live_…'`).

const { domain, page_size } = $input.first().json;
const limit = Math.min(500, Math.max(1, Number(page_size) || 100));
const apiKey = $env.SUBSPACE_API_KEY;

if (!apiKey) {
  throw new Error("Missing API key. Set SUBSPACE_API_KEY in your n8n environment, or hard-code the key in this Code node.");
}

const all = [];
let offset = 0;
let pages = 0;
const MAX_PAGES = 50; // safety cap — 50 × 500 = 25,000 jobs

while (pages < MAX_PAGES) {
  const url = new URL('https://www.thesubspace.io/api/v1/enrich');
  url.searchParams.set('domain', domain);
  url.searchParams.set('include', 'jobs');
  url.searchParams.set('jobs_limit', String(limit));
  url.searchParams.set('jobs_offset', String(offset));

  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: url.toString(),
    headers: { 'x-api-key': apiKey },
    json: true,
  });

  for (const job of (res.jobs || [])) {
    all.push({ ...job, company_domain: domain });
  }

  pages += 1;
  if (!res.jobs_has_more || res.jobs_next_offset == null) break;
  offset = res.jobs_next_offset;
}

return all.map(j => ({ json: j }));
